solution.solution.cpp:
#include <vector>

std::vector<int> countdown(int from)
{
    std::vector<int> result{};
    for (int i{ from }; i >= 1; --i)
    {
        result.push_back(i);
    }
    return result;
}

unitTests:
TEST("from four") { CHECK_EQ(countdown(4), (std::vector<int>{ 4, 3, 2, 1 })); }
TEST("from one") { CHECK_EQ(countdown(1), (std::vector<int>{ 1 })); }
TEST("nothing to count") { CHECK(countdown(0).empty()); CHECK(countdown(-3).empty()); }

